function ai(x) {
	mt = "MAŠĪNTULKOJUMS";
	if ( x==null) x = "MI&nbsp;&nbsp;TULKOJUMS";
	else x = mt + " " + x;
	returnText =  "<br><span style =' font-size: calc(var(--font-unit) * 0.6);'>" + x + "</span>";
return returnText;
  }

